<?php
namespace App\Http\Controllers;
use App\Models\{Booking,CheckoutAttempt,GatewayAccount};use App\Services\Payments\{GatewayDriver,PaymentService};use Illuminate\Http\Request;
class CheckoutController extends Controller {
 private function own(Request $r,Booking $b){abort_unless($r->user()->id===$b->user_id,403);}
 private function display(CheckoutAttempt $a){$state=app(\App\Services\Payments\GatewayCredentials::class)->read($a->account);$c=$state['value'];return array_merge($a->only('id','booking_id','provider','purpose','amount','currency','status','checkout','expires_at','external_id'),['customer_message'=>\App\Services\Payments\CustomerPaymentStatus::message($a),'review_reason'=>\App\Services\Payments\CustomerPaymentStatus::message($a),'sdk'=>['client_id'=>$a->provider==='paypal'?($c['client_id']??null):null,'public_key'=>$a->provider==='mercadopago'?($c['public_key']??null):null],'credential_warning'=>$state['unreadable']?'El establecimiento está revisando este pago. Puedes contactarlo desde tu reservación.':null,'payment_attention'=>$a->booking->payment_attention?'El establecimiento está revisando un detalle de tu reservación. Contacta al negocio para recibir ayuda.':null,'booking_paid_total'=>$a->booking->paid_total]);}
 public function options(Request $r,Booking $booking){
 $this->own($r,$booking);$reader=app(\App\Services\Payments\GatewayCredentials::class);$windows=app(\App\Services\Payments\CheckoutWindow::class);
 return ['booking'=>['id'=>$booking->id,'venue_name'=>$booking->venue->name,'order_number'=>$booking->order_number,'starts_at'=>$booking->starts_at->toIso8601String(),'timezone'=>$booking->quote['timezone']??$booking->venue->settings['timezone'],'status'=>$booking->status,'deposit'=>$booking->deposit,'paid_total'=>$booking->paid_total,'balance_due'=>$booking->balance_due],
 'providers'=>GatewayAccount::where('venue_id',$booking->venue_id)->where('current',true)->where('enabled',true)->get()->filter(fn($g)=>$reader->usable($g))->map(function($g)use($reader,$windows,$booking){$c=$reader->read($g)['value'];return array_merge(['provider'=>$g->provider,'sandbox'=>$g->sandbox,'client_id'=>$g->provider==='paypal'?($c['client_id']??null):null,'public_key'=>$g->provider==='mercadopago'?($c['public_key']??null):null],$windows->assess($booking,$g->provider));})->values()->toArray()];
 }
 public function start(Request $r,Booking $booking,PaymentService $payments,GatewayDriver $driver){$this->own($r,$booking);$d=$r->validate(['policy_accepted'=>'required|accepted','provider'=>'required|in:paypal,mercadopago,oxxo','purpose'=>'required|in:deposit,balance','phone'=>'nullable|string|max:30']);if($d['provider']==='oxxo'&&!$r->user()->phone){abort_unless(filled($d['phone']??null),422,'OXXO Pay requiere un teléfono de contacto para emitir la ficha.');$r->user()->update(['phone'=>$d['phone']]);}return $this->display($payments->start($booking,$d['provider'],$d['purpose'],$driver,true));}
 public function card(Request $r,CheckoutAttempt $attempt,GatewayDriver $driver,PaymentService $payments){
 $this->own($r,$attempt->booking);abort_unless($attempt->provider==='mercadopago'&&($attempt->checkout['mode']??'')==='embedded',422);
 $d=$r->validate(['token'=>'required|string|max:200','payment_method_id'=>'required|regex:/^[a-zA-Z0-9_]{1,50}$/','installments'=>'required|integer|between:1,36','issuer_id'=>'nullable|regex:/^[0-9]{1,30}$/','payer'=>'sometimes|array','payer.identification'=>'sometimes|array:type,number','payer.identification.type'=>'required_with:payer.identification|string|max:30','payer.identification.number'=>'required_with:payer.identification|string|max:50']);
 $payments->authorizeCapture($attempt);
 \Illuminate\Support\Facades\DB::transaction(function()use($attempt){$a=CheckoutAttempt::whereKey($attempt->id)->lockForUpdate()->firstOrFail();abort_unless($a->status==='pending'&&$a->expires_at->isFuture()&&empty($a->checkout['card_submitted']),422,'Este intento ya se envió o venció. Consulta su estado antes de volver a pagar.');$a->update(['checkout'=>array_merge($a->checkout,['card_submitted'=>true])]);});
 try{$id=$driver->card($attempt,$d);$attempt->refresh();$attempt->update(['checkout'=>array_merge($attempt->checkout,['payment_id'=>$id])]);$data=$driver->read($attempt->account,$id);$payments->settle($attempt->account,$data);$attempt->refresh();if(!$data['paid']){if(in_array($data['provider_status']??'',['rejected','cancelled']))$attempt->update(['status'=>'failed','review_reason'=>'La tarjeta fue rechazada. No se confirmó ningún pago. Puedes iniciar un nuevo intento.']);}}
 catch(\Throwable $e){app(\App\Services\Payments\PaymentFailure::class)->record($attempt,$e,'card');$attempt->refresh();if(!in_array($attempt->status,['paid','review']))$attempt->update(['status'=>'unknown','review_reason'=>'Estamos comprobando el estado del pago.']);return $this->display($attempt->fresh());}
 return $this->display($attempt->fresh());
 }
 public function sync(Request $r,CheckoutAttempt $attempt,GatewayDriver $driver,PaymentService $payments,\App\Services\Payments\PaymentSync $sync){$this->own($r,$attempt->booking);return $this->display($sync->sync($attempt,$driver,$payments));}
 public function show(Request $r,CheckoutAttempt $attempt){$this->own($r,$attempt->booking);return $this->display($attempt);}
 public function capture(Request $r,CheckoutAttempt $attempt,GatewayDriver $driver,PaymentService $payments){$this->own($r,$attempt->booking);abort_unless($attempt->provider==='paypal'&&$attempt->external_id,422);if($attempt->paid_transaction_id)return $this->display($attempt);
 try{$data=$driver->read($attempt->account,$attempt->external_id);if(!$data['paid']){$payments->authorizeCapture($attempt,true);$driver->capture($attempt);$data=$driver->read($attempt->account,$attempt->external_id);}$payments->settle($attempt->account,$data);return $this->display($attempt->fresh());}
 catch(\Illuminate\Http\Client\RequestException|\Illuminate\Http\Client\ConnectionException $e){app(\App\Services\Payments\PaymentFailure::class)->record($attempt,$e,'capture');$attempt->refresh();if(!$attempt->paid_transaction_id)$attempt->update(['status'=>'unknown','review_reason'=>'Estamos comprobando el estado del pago.']);return $this->display($attempt->fresh());}
 }
 public function reconcile(Request $r,CheckoutAttempt $attempt,GatewayDriver $driver,PaymentService $payments){$this->own($r,$attempt->booking);$id=$attempt->external_id;if($attempt->provider==='mercadopago'){$d=$r->validate(['payment_id'=>'nullable|regex:/^[0-9]{1,30}$/']);$id=$attempt->checkout['payment_id']??($d['payment_id']??null);}abort_unless($id,422,'La orden aún no tiene identificador del proveedor.');$data=$driver->read($attempt->account,$id);abort_unless($data['reference']===$attempt->id,422);$payments->settle($attempt->account,$data);return $this->display($attempt->fresh());}
}
